import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {checkReport} from './schema-report-gate.mjs';
// Reduced retained Node26 report from run 41792404917; not a substitute for a fresh physical run.
const good=JSON.parse(readFileSync(new URL('./owned-schema-gate-fixture.json',import.meta.url),'utf8'));
// Generated by the pinned handler/wrapper with modeled DB outcomes; not a physical run.
good.sdk50=JSON.parse(readFileSync(new URL('./sdk50-gate-fixture.json',import.meta.url),'utf8'));
const manifest=JSON.parse(readFileSync(new URL('../../../tests/fixtures/schema-list-original-2.7/manifest.json',import.meta.url),'utf8'));
good.sdk50Sources=Object.values(manifest.sources).map(({path,bytes,sha256,gitBlob})=>({path,bytes,sha256,gitBlob}));
test('real-shaped successful receipt passes, while incomplete or failed cleanup fails',()=>{
 checkReport(good);
 for(const mutate of [r=>{r.status='failed';},r=>{r.completedAt=null;},r=>{r.connectionClose.succeeded=false;},r=>{r.royaltyTemplate=null;},
  r=>{r.ownedSchema.rollbackSucceeded=false;},r=>{r.ownedSchema.baseline='other';},r=>{r.reference.commit='other';},r=>{r.admission.version='16.14';},
  r=>{delete r.sdk50;},r=>{r.sdk50.status='failed';},r=>{r.sdk50.cleanup=[];},r=>{r.sdk50.operations[3].dbError.code='XX000';},
  r=>{r.ownedSource[0].fixtureSha256='wrong';},r=>{r.ownedSource.push(r.ownedSource[0]);}]){
  const r=structuredClone(good);mutate(r);assert.throws(()=>checkReport(r));
 }
});
test('SDK50 persisted gate accepts either consistent off-page result and rejects missing or inconsistent evidence',()=>{
 const ok=structuredClone(good),row=ok.sdk50.operations[1];row.dbTerminal='returned';row.dbError=null;row.rowCount=1;
 row.http={status:200,body:{success:true,data:[{schema_name:'missing',contract:'atomicassets',collection:{collection_name:'colone'},assets:0}],query_time:1}};checkReport(ok);
 for(const mutate of [r=>{delete r.sdk50Sources;},r=>{r.sdk50Sources[0].sha256='wrong';},r=>{r.sdk50Sources.push(r.sdk50Sources[0]);},
  r=>{r.sdk50.setup[1].sql='SET LOCAL statement_timeout = 0';},r=>{r.sdk50.operations[0].params.schema_name='other';},
  r=>{r.sdk50.operations[1].sql=null;},r=>{r.sdk50.operations[1].bindings=['atomicassets','other',1,0];},
  r=>{r.sdk50.operations[1].dbTerminal='returned';},r=>{r.sdk50.operations[1].dbError.code='57014';},
  r=>{r.sdk50.operations[2].rowCount=0;},r=>{r.sdk50.operations[2].http.body.data='5';},
  r=>{r.sdk50.operations[3].sql='SELECT 1';},r=>{r.sdk50.operations[3].dbTerminal='returned';},
  r=>{r.sdk50.operations[3].dbError.message='cancelled by user';},r=>{r.sdk50.operations[3].http.body.message='other';},
  r=>{r.sdk50.cleanup[0].released=false;}]){
  const r=structuredClone(good);mutate(r);assert.throws(()=>checkReport(r));
 }
 for(const mutate of [r=>{r.sdk50.operations[1].rowCount=0;},r=>{r.sdk50.operations[1].http.body.data=[];},
  r=>{r.sdk50.operations[1].http.body.data[0].schema_name='positive';},
  r=>{r.sdk50.operations[1].http.body.data[0].schema_name='peer';},
  r=>{r.sdk50.operations[1].http.body.data[0].schema_name='zero';},r=>{r.sdk50.operations[1].http.body.data[0].collection.collection_name='coltwo';},
  r=>{r.sdk50.operations[1].http.body.data[0].assets=1;},r=>{r.sdk50.operations[1].dbError={code:'22003'};}]){
  const r=structuredClone(ok);mutate(r);assert.throws(()=>checkReport(r));
 }
});
test('missing, contradictory or reordered snapshots and event ranges fail',()=>{
 for(const mutate of [r=>{r.ownedSchema.snapshots=r.ownedSchema.snapshots.map(({name})=>({name}));},
  r=>{r.ownedSchema.snapshots[1].handlerRows=[];},r=>{r.ownedSchema.snapshots[1].counts[0].owned='1';},
  r=>{r.ownedSchema.snapshots[1].eventStart++;},r=>{r.ownedSchema.snapshots[1].eventEnd--;},
  r=>{r.ownedSchema.events[12].rows=[];},r=>{r.ownedSchema.events[13].rows[0].owned='0';},
  r=>{r.ownedSchema.events[12].label='empty:handler';},r=>{r.ownedSchema.events.splice(12,0,structuredClone(r.ownedSchema.events[12]));},
  r=>{[r.ownedSchema.snapshots[1],r.ownedSchema.snapshots[2]]=[r.ownedSchema.snapshots[2],r.ownedSchema.snapshots[1]];}]){
  const r=structuredClone(good);mutate(r);assert.throws(()=>checkReport(r));
 }
});
test('trigger, SQL, bindings, row counts and rollback evidence cannot be placeholders',()=>{
 for(const mutate of [r=>{r.ownedSchema.events[0].rows=[{}];},r=>{r.ownedSchema.events[0].rows[0].tgenabled='D';},
  r=>{r.ownedSchema.events[0].rows[0].function_definition='update_atomicassets_asset_counts';},
  r=>{r.ownedSchema.events[0].rows[0].function_definition=r.ownedSchema.events[0].rows[0].function_definition.replace('OLD.owner IS DISTINCT FROM NEW.owner','FALSE');},
  r=>{r.ownedSchema.events[8].sql='SELECT 1';},r=>{r.ownedSchema.events[14].bindings[0]='eve';},
  r=>{r.ownedSchema.events[17].status='error';},r=>{r.ownedSchema.events[21].rowCount=0;},
  r=>{r.ownedSchema.events[24].sql='ROLLBACK';},r=>{r.ownedSchema.events[33].rows=[{}];},
  r=>{r.ownedSchema.events[6].bindings[1]='other';}]){
  const r=structuredClone(good);mutate(r);assert.throws(()=>checkReport(r));
 }
});
